   （生=浅蓝 / 恰好=绿 / 过火=橙 / 糊=红 这四档语义一个都没改）*/
g.lineWidth = 13; g.strokeStyle = "rgba(10,7,4,.55)";
g.beginPath(); g.arc(cx, cy, rr, 0, Math.PI * 2); g.stroke();
